-- Initial identity inspection:
BEGIN READ ONLY; SELECT current_setting('transaction_read_only') AS transaction_read_only, current_database() AS database, current_user AS current_user, session_user AS session_user, version() AS postgresql_version, clock_timestamp() AS inspected_at, current_setting('cluster_name',true) AS cluster_name; ROLLBACK;

-- Final read-only catalog stability recheck:
BEGIN READ ONLY;SELECT clock_timestamp() AS inspected_at,current_setting('transaction_read_only') AS transaction_read_only,jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'hash',md5(replace(p.prosrc,chr(13),'')),'owner',p.proowner::regrole::text,'definer',p.prosecdef,'acl',p.proacl::text,'config',p.proconfig) ORDER BY p.oid::regprocedure::text) AS functions FROM pg_proc p WHERE p.oid IN ('public.authorize_my_routing_candidate(uuid,uuid,timestamp with time zone)'::regprocedure,'public.cancel_claim(uuid,uuid)'::regprocedure,'public.cancel_my_unstarted_route(uuid)'::regprocedure,'public.claim_listing(uuid,uuid)'::regprocedure,'public.close_my_collected_route(uuid,boolean)'::regprocedure,'public.close_my_resolved_route(uuid,boolean,uuid)'::regprocedure,'public.complete_pickup(uuid,boolean)'::regprocedure,'public.confirm_my_route_depot_checkpoint(uuid,boolean,uuid)'::regprocedure,'public.defer_my_pickup_for_reconciliation(uuid,uuid)'::regprocedure,'public.enforce_listing_transition()'::regprocedure,'public.finalize_route_resolution(uuid,bigint,uuid)'::regprocedure,'public.geolock_listing_eligibility_trigger()'::regprocedure,'public.geolock_lock_listing_donations(uuid,text[])'::regprocedure,'public.geolock_prepare_listing_eligibility()'::regprocedure,'public.geolock_transition_listing_donations(uuid,text,text)'::regprocedure,'public.geolock_transition_listing_donations(uuid,text,text,uuid,uuid,text)'::regprocedure,'public.recover_expired_claims(integer)'::regprocedure,'public.report_my_route_interruption(uuid,text,uuid)'::regprocedure,'public.resolve_my_claim_reconciliation(uuid,uuid)'::regprocedure,'public.review_my_claim_reconciliation(uuid,text,bigint,uuid)'::regprocedure,'public.start_pickup(uuid)'::regprocedure,'public.submit_claim_reconciliation(uuid,boolean,uuid)'::regprocedure,'public.submit_claim_reconciliation_v2(uuid,boolean,integer,bigint,uuid)'::regprocedure,'public.submit_route_resolution_evidence(uuid,uuid,text,bigint,uuid)'::regprocedure,'resolution_private.lock_case(uuid)'::regprocedure,'routing_private.coord_decide(uuid,uuid)'::regprocedure,'routing_private.legacy_complete_pickup(uuid,boolean)'::regprocedure,'routing_private.legacy_start_pickup(uuid)'::regprocedure,'routing_private.lock_reconciliation_scope(uuid)'::regprocedure,'routing_private.lock_route(uuid,boolean)'::regprocedure,'routing_private.lock_route_for_recovery(uuid)'::regprocedure,'routing_private.lock_sources(uuid[])'::regprocedure);ROLLBACK;
